                                    item=${item}
                                    last=${index === items.length - 1}
                                    busy=${busy}
                                    conversationId=${id}
                                />`,
                        )} ${ready &&
                busy &&
                !speaking &&
                items.at(-1)?.type !== "activity" &&
                html`<div class="pip-steps working">
                    <${Spinner} hidden=${true} />
                    <span>Thinking</span>
                </div>`} ${pending.map(
                (item) => html`<div class="pip-you pending" key=${`pending-${item.id}`}>
