            me?.role === "owner" &&
            memoryAvailable(id) &&
            html`<${PendingMemories} id=${id} />`}

${!streaming &&
                html`<span class="rich-tabs" role="tablist">
                    <button
                        type="button"
                        role="tab"
                        aria-selected=${view === "shown" ? "true" : "false"}
