                        role="tab"
                        aria-selected=${view === "code" ? "true" : "false"}
                        class=${view === "code" ? "on" : ""}
                        onClick=${() => setView("code")}
                    >
                        Code
                    </button>
                </span>`}

${kind === "html" &&
                !code &&
                html`<button
