                class=${`board-need ${state} ${agent.conversationId === selected ? "on" : ""}`}
                onClick=${() => onPick(agent.conversationId)}
            >
                <${Mark} state=${state} />
                <span class="board-need-main">
                    <span class="board-need-head">
                        <b>${agent.name}</b>${" "}<span class="board-need-what">
