${active.length > 0 &&
                html`<div class="board-live" role="group" aria-label="Subagents at work">
                    ${tiles.map(
                        (agent) => html`<${AgentTile}
                            key=${agent.conversationId}
                            agent=${agent}
                            folder=${folder}
                            selected=${agent.conversationId === selected}
                            onActivate=${() => pick(agent.conversationId)}
                            onOpen=${() => open(agent)}
